import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const files = {
  "dist/app.js": "",
  "dist/assets/brand-lockup.png": "",
  "dist/assets/brand-mark.png": "",
  "dist/assets/hero-city.jpg": "",
  "dist/index.html": "",
  "dist/manifest.webmanifest": "",
  "dist/styles.css": "",
  "netlify/functions/analyze.mjs": "",
  "netlify/functions/health.mjs": "",
  "netlify/functions/lib/analysis-core.mjs": "",
  "netlify/functions/lib/environment-client.mjs": "",
  "netlify/functions/lib/geo.mjs": "",
  "netlify/functions/lib/http.mjs": "",
  "netlify/functions/lib/tkgm-api.mjs": "",
  "netlify/functions/lib/tkgm-client.mjs": "",
  "netlify/functions/lib/zoning-client.mjs": "",
  "netlify/functions/request-analysis.mjs": "",
  "netlify/functions/tkgm.mjs": "",
  "netlify/functions/user-data.mjs": ""
};

await rm('dist', { recursive: true, force: true });
await rm('netlify/functions', { recursive: true, force: true });

for (const [path, encoded] of Object.entries(files)) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, Buffer.from(encoded, 'base64'));
}

for (const path of [
  'dist/app.js',
  'netlify/functions/tkgm.mjs',
  'netlify/functions/analyze.mjs',
  'netlify/functions/user-data.mjs',
  'netlify/functions/request-analysis.mjs'
]) {
  await execFileAsync(process.execPath, ['--check', path]);
}

const html = Buffer.from(files['dist/index.html'], 'base64').toString('utf8');
const app = Buffer.from(files['dist/app.js'], 'base64').toString('utf8');
const required = ['summaryGrid', 'possibilityGrid', 'environmentGrid', 'claimList', '/api/analyze', '/api/request-analysis'];
for (const marker of required) {
  if (!html.includes(marker) && !app.includes(marker)) throw new Error(`Eksik build işareti: ${marker}`);
}

console.log(`Planlamasyon v3.1 build tamamlandı: ${Object.keys(files).length} dosya üretildi.`);
